import type {
  NormalizedFinding,
  SeverityLevel,
  SonarHotspotsBreakdown,
  SonarIssueRecord,
} from '../../types/benchmark';
import { computeSha256, enrichLegacyOrExternalFinding } from '../../engine/scoringEngine';

const EXTERNAL_ENGINE_META: Record<string, { name: string; defaultVersion: string }> = {
  semgrep: { name: 'Semgrep / Opengrep SARIF', defaultVersion: '1.9.2' },
  opengrep: { name: 'Opengrep SAST SARIF', defaultVersion: '1.9.2' },
  codeql: { name: 'GitHub CodeQL SARIF', defaultVersion: '2.19.0' },
  gitleaks: { name: 'Gitleaks Secret Scanner SARIF', defaultVersion: '8.21.2' },
  trivy: { name: 'Aqua Trivy SARIF', defaultVersion: '0.57.1' },
  bandit: { name: 'PyCQA Bandit SARIF', defaultVersion: '1.7.10' },
  ruff: { name: 'Astral Ruff SARIF', defaultVersion: '0.7.3' },
  eslint: { name: 'ESLint Static Report', defaultVersion: '9.14.0' },
  spotbugs: { name: 'SpotBugs Bytecode Analyzer', defaultVersion: '4.8.6' },
  pmd: { name: 'PMD Source Code Analyzer', defaultVersion: '7.7.0' },
  checkstyle: { name: 'Checkstyle Java Auditor', defaultVersion: '10.20.1' },
};

export interface RawSonarHotspotItem {
  key: string;
  component: string;
  project: string;
  securityCategory: string;
  vulnerabilityProbability: 'HIGH' | 'MEDIUM' | 'LOW';
  status: 'TO_REVIEW' | 'REVIEWED';
  resolution?: 'FIXED' | 'SAFE' | 'ACKNOWLEDGED' | 'VULNERABLE';
  line?: number;
  message: string;
  ruleKey?: string;
}

/**
 * SonarResultParser (Seção 6.2, Seção 7 e Seção 10)
 * Converte issues e Security Hotspots da Web API do SonarQube / SonarCloud para o formato auditável do WinHood.
 * - Distingue achados nativos das regras do SonarQube de achados externos importados via SARIF (`externalRuleEngine`).
 * - Separa Security Hotspots por estado real de revisão (TO_REVIEW, SAFE, FIXED, ACKNOWLEDGED, VULNERABLE),
 *   sem nunca classificar um hotspot SAFE ou ACKNOWLEDGED como vulnerabilidade corrigida (FIXED).
 */
export class SonarResultParser {
  public static parseEffortToMinutes(effortStr?: string): number {
    if (!effortStr) return 10;
    let total = 0;
    const hMatch = effortStr.match(/\b(\d{1,6})h\b/);
    const mMatch = effortStr.match(/\b(\d{1,6})min\b/);
    const dMatch = effortStr.match(/\b(\d{1,6})d\b/);
    if (dMatch) total += Number.parseInt(dMatch[1], 10) * 480;
    if (hMatch) total += Number.parseInt(hMatch[1], 10) * 60;
    if (mMatch) total += Number.parseInt(mMatch[1], 10);
    return total > 0 ? total : 10;
  }

  /**
   * Calcula o detalhamento estrito de Security Hotspots (Seção 10).
   * - Não converte erro de API em 0 hotspots ou 100% revisados.
   * - Nunca soma SAFE ou ACKNOWLEDGED dentro de reviewedFixedCount.
   */
  public static computeHotspotsBreakdown(
    rawHotspots: RawSonarHotspotItem[] | null | undefined,
    options?: {
      apiError?: boolean;
      isPartial?: boolean;
      measuredReviewPercentFromApi?: number | null;
    }
  ): SonarHotspotsBreakdown {
    if (options?.apiError || !rawHotspots) {
      return {
        totalIdentified: null,
        reviewedCount: null,
        unreviewedCount: null,
        reviewedSafeCount: null,
        reviewedVulnerableCount: null,
        reviewedFixedCount: null,
        acceptedRiskCount: null,
        reviewPercent: null,
        measurementState: options?.apiError ? 'API_ERROR' : 'NOT_MEASURED',
      };
    }

    let reviewedCount = 0;
    let unreviewedCount = 0;
    let reviewedSafeCount = 0;
    let reviewedVulnerableCount = 0;
    let reviewedFixedCount = 0;
    let acceptedRiskCount = 0;

    for (const hs of rawHotspots) {
      if (hs.status === 'REVIEWED') {
        reviewedCount += 1;
        if (hs.resolution === 'SAFE') {
          reviewedSafeCount += 1;
        } else if (hs.resolution === 'FIXED') {
          reviewedFixedCount += 1;
        } else if (hs.resolution === 'ACKNOWLEDGED') {
          acceptedRiskCount += 1;
        } else if (hs.resolution === 'VULNERABLE') {
          reviewedVulnerableCount += 1;
        }
      } else {
        unreviewedCount += 1;
      }
    }

    const totalIdentified = rawHotspots.length;
    let reviewPercent: number | null = null;
    if (
      options?.measuredReviewPercentFromApi !== undefined &&
      options.measuredReviewPercentFromApi !== null
    ) {
      reviewPercent = options.measuredReviewPercentFromApi;
    } else if (totalIdentified > 0) {
      reviewPercent = Number(((reviewedCount / totalIdentified) * 100).toFixed(1));
    }

    return {
      totalIdentified,
      reviewedCount,
      unreviewedCount,
      reviewedSafeCount,
      reviewedVulnerableCount,
      reviewedFixedCount,
      acceptedRiskCount,
      reviewPercent,
      measurementState: options?.isPartial ? 'PARTIAL' : 'MEASURED',
    };
  }

  public static parseIssuesAndHotspots(params: {
    analysisId: string;
    projectKey: string;
    softwareId: string;
    softwareName: string;
    rawIssues: Array<{
      key: string;
      rule: string;
      severity: 'BLOCKER' | 'CRITICAL' | 'MAJOR' | 'MINOR' | 'INFO';
      component: string;
      project: string;
      line?: number;
      message: string;
      effort?: string;
      type: 'BUG' | 'VULNERABILITY' | 'CODE_SMELL';
      externalRuleEngine?: string;
    }>;
    rawHotspots?: RawSonarHotspotItem[];
  }): SonarIssueRecord[] {
    const records: SonarIssueRecord[] = [];
    const seenFingerprints = new Set<string>();

    for (const item of params.rawIssues) {
      const filePath = item.component.includes(':')
        ? item.component.split(':').slice(1).join(':')
        : item.component;
      const lineNumber = item.line || 1;

      const isExternal =
        Boolean(item.externalRuleEngine) || item.rule.startsWith('external_');
      const engineKey = (
        item.externalRuleEngine ||
        (item.rule.startsWith('external_')
          ? item.rule.replace(/^external_/, '').split(':')[0]
          : '')
      ).toLowerCase();

      const externalMeta = EXTERNAL_ENGINE_META[engineKey];
      const originalRuleId = item.rule.includes(':')
        ? item.rule.split(':').slice(1).join(':')
        : item.rule;

      // Deduplicação determinística por (softwareId, filePath, lineNumber, originalRuleId)
      const dedupKey = `${params.softwareId}|${filePath}|${lineNumber}|${originalRuleId}`;
      if (seenFingerprints.has(dedupKey)) {
        continue;
      }
      seenFingerprints.add(dedupKey);

      const evidenceSha256 = computeSha256(
        `${params.analysisId}|${item.key}|${item.rule}|${filePath}:${lineNumber}|${item.message}`
      );

      records.push({
        id: `siss-${evidenceSha256.slice(0, 12)}`,
        issueKey: item.key,
        analysisId: params.analysisId,
        projectKey: params.projectKey,
        softwareId: params.softwareId,
        softwareName: params.softwareName,
        type: item.type,
        severity: item.severity,
        ruleKey: item.rule,
        ruleName: isExternal
          ? `[Importado via SARIF: ${externalMeta?.name || engineKey.toUpperCase()}] ${originalRuleId}`
          : `Regra Nativa SonarQube (${item.rule})`,
        isExternalImportedRule: isExternal,
        externalOriginTool: isExternal
          ? externalMeta?.name || engineKey.toUpperCase()
          : 'SonarQube / SonarCloud (Nativo)',
        externalOriginVersion: isExternal
          ? externalMeta?.defaultVersion || 'SARIF 2.1.0'
          : '26.11.0.134175',
        originalRuleId,
        confidence:
          item.severity === 'BLOCKER' || item.severity === 'CRITICAL'
            ? 'HIGH'
            : 'MEDIUM',
        filePath,
        lineNumber,
        message: item.message,
        effortMinutes: SonarResultParser.parseEffortToMinutes(item.effort),
        remediationGuidance: isExternal
          ? 'Achado importado de relatório externo (SARIF). Regras externas não fazem parte do Quality Profile nativo do SonarQube; valide a correção na ferramenta de origem.'
          : 'Consulte a orientação Clean as You Code da regra nativa no perfil de qualidade ativo do projeto.',
        evidenceSnippet: `${filePath}:${lineNumber} — ${item.message}`,
        evidenceSha256,
      });
    }

    for (const hs of params.rawHotspots || []) {
      const filePath = hs.component.includes(':')
        ? hs.component.split(':').slice(1).join(':')
        : hs.component;
      const lineNumber = hs.line || 1;
      const ruleKey = hs.ruleKey || `hotspot:${hs.securityCategory}`;
      const evidenceSha256 = computeSha256(
        `${params.analysisId}|HOTSPOT|${hs.key}|${filePath}:${lineNumber}|${hs.message}`
      );

      let reviewStatus: SonarIssueRecord['hotspotReviewStatus'] = 'TO_REVIEW';
      let guidance =
        'Security Hotspot pendente de revisão humana (TO_REVIEW): pontos sensíveis à segurança exigem inspeção manual para determinar se o contexto expõe uma vulnerabilidade explorável.';
      if (hs.status === 'REVIEWED') {
        if (hs.resolution === 'SAFE') {
          reviewStatus = 'REVIEWED_SAFE';
          guidance =
            'Security Hotspot revisado como SEGURO (REVIEWED_SAFE): auditado manualmente sem risco explorável no contexto atual (não contabilizado como vulnerabilidade corrigida).';
        } else if (hs.resolution === 'FIXED') {
          reviewStatus = 'REVIEWED_FIXED';
          guidance =
            'Security Hotspot revisado como CORRIGIDO (REVIEWED_FIXED): mitigação técnica aplicada no código.';
        } else if (hs.resolution === 'VULNERABLE') {
          reviewStatus = 'REVIEWED_VULNERABLE';
          guidance =
            'Security Hotspot revisado e confirmado como VULNERÁVEL (REVIEWED_VULNERABLE): requer correção prioritária.';
        } else {
          reviewStatus = 'REVIEWED_ACKNOWLEDGED';
          guidance =
            'Security Hotspot com RISCO ACEITO / RECONHECIDO (REVIEWED_ACKNOWLEDGED): risco documentado pela equipe sem alteração imediata de código (não equivale a correção).';
        }
      }

      records.push({
        id: `shs-${evidenceSha256.slice(0, 12)}`,
        issueKey: hs.key,
        analysisId: params.analysisId,
        projectKey: params.projectKey,
        softwareId: params.softwareId,
        softwareName: params.softwareName,
        type: 'SECURITY_HOTSPOT',
        severity:
          hs.vulnerabilityProbability === 'HIGH'
            ? 'CRITICAL'
            : hs.vulnerabilityProbability === 'MEDIUM'
              ? 'MAJOR'
              : 'MINOR',
        ruleKey,
        ruleName: `Security Hotspot (${hs.securityCategory})`,
        isExternalImportedRule: false,
        externalOriginTool: 'SonarQube Security Hotspot Engine (Estático)',
        externalOriginVersion: '26.11.0.134175',
        originalRuleId: ruleKey,
        confidence: hs.vulnerabilityProbability,
        filePath,
        lineNumber,
        message: hs.message,
        effortMinutes: 20,
        remediationGuidance: guidance,
        hotspotReviewStatus: reviewStatus,
        evidenceSnippet: `${filePath}:${lineNumber} [${hs.securityCategory}] (${reviewStatus})`,
        evidenceSha256,
      });
    }

    return records;
  }

  /**
   * Converte issues e hotspots do SonarCloud para o modelo NormalizedFinding da plataforma WinHood,
   * preservando que Security Hotspots NUNCA sejam classificados como vulnerabilidades confirmadas (CONFIRMED)
   * a menos que tenham sido revisados explicitamente como REVIEWED_VULNERABLE.
   */
  public static mapSonarIssuesToNormalizedFindings(
    issues: SonarIssueRecord[],
    softwareId: string,
    softwareName: string
  ): NormalizedFinding[] {
    return issues.map((iss) => {
      let category: NormalizedFinding['category'] = 'CODE_QUALITY';
      const ruleLow = (iss.ruleKey || '').toLowerCase();
      const msgLow = (iss.message || '').toLowerCase();

      if (
        ruleLow.includes('sql') ||
        ruleLow.includes('injection') ||
        ruleLow.includes('database') ||
        ruleLow.includes('db') ||
        msgLow.includes('sql') ||
        msgLow.includes('database') ||
        msgLow.includes('query')
      ) {
        category = 'DATABASE';
      } else if (
        ruleLow.includes('secret') ||
        ruleLow.includes('password') ||
        ruleLow.includes('token') ||
        ruleLow.includes('auth') ||
        ruleLow.includes('key') ||
        ruleLow.includes('credential') ||
        msgLow.includes('password') ||
        msgLow.includes('token') ||
        msgLow.includes('credential') ||
        msgLow.includes('secret')
      ) {
        category = 'SECRETS';
      } else if (
        ruleLow.includes('http') ||
        ruleLow.includes('cors') ||
        ruleLow.includes('ssrf') ||
        ruleLow.includes('xss') ||
        ruleLow.includes('csrf') ||
        ruleLow.includes('tls') ||
        ruleLow.includes('ssl') ||
        ruleLow.includes('network') ||
        msgLow.includes('http') ||
        msgLow.includes('network') ||
        msgLow.includes('endpoint')
      ) {
        category = 'SAST';
      } else if (iss.type === 'VULNERABILITY' || iss.type === 'SECURITY_HOTSPOT') {
        category = 'SAST';
      } else if (ruleLow.includes('dep') || ruleLow.includes('cve') || ruleLow.includes('vulnerability')) {
        category = 'SCA';
      } else if (ruleLow.includes('arch') || ruleLow.includes('cycle') || ruleLow.includes('coupling')) {
        category = 'ARCHITECTURE';
      }

      const mappedSeverity: SeverityLevel =
        iss.severity === 'BLOCKER'
          ? 'BLOCKER'
          : iss.severity === 'CRITICAL'
            ? 'CRITICAL'
            : iss.severity === 'MAJOR'
              ? 'HIGH'
              : iss.severity === 'MINOR'
                ? 'MEDIUM'
                : 'INFO';

      const validationStatus: NormalizedFinding['validationStatus'] =
        iss.type === 'SECURITY_HOTSPOT'
          ? iss.hotspotReviewStatus === 'REVIEWED_VULNERABLE'
            ? 'CONFIRMED'
            : 'UNVERIFIED'
          : 'CONFIRMED';

      return enrichLegacyOrExternalFinding({
        id: `fnd-sonar-${iss.issueKey || iss.id}`,
        runId: 'run-sonarcloud-live',
        softwareId,
        softwareName,
        softwareVersion: '1.0.0',
        toolId: iss.isExternalImportedRule ? 'external-sarif' : 'sonarcloud-sast',
        toolName: iss.externalOriginTool || 'SonarCloud SaaS Official',
        toolVersion: iss.externalOriginVersion || '8.0.0.117526',
        category,
        originalRuleId: iss.originalRuleId || iss.ruleKey,
        title: iss.ruleName || iss.ruleKey,
        description: iss.message || 'SonarCloud rule detection',
        severity: mappedSeverity,
        confidence: iss.confidence || 'HIGH',
        filePath: iss.filePath,
        lineNumber: iss.lineNumber,
        snippet: iss.evidenceSnippet,
        remediation: iss.remediationGuidance || 'Consulte a documentação da regra do SonarCloud.',
        remediationEffortMinutes: iss.effortMinutes || 20,
        evidenceSha256: iss.evidenceSha256 || computeSha256(`${iss.ruleKey}:${iss.filePath}:${iss.lineNumber}`),
        validationStatus,
      });
    });
  }
}
